// Durability is broker-side: reuse `identifier` and let the session outlive the connection
// (MQTT 5 session expiry / MQTT 3.1.1 clean session disabled), then subscribe at QoS 1.
try await MQTTConnection.withConnection(
    address: .hostname("broker"), identifier: "billing-ledger"
) { connection in
    try await connection.subscribe(to: [.init(topicFilter: "orders/#", qos: .atLeastOnce)]) { sub in
        for try await message in sub { handle(message) }   // idempotent: QoS 1 redelivers
    }
}
